'use client';

import * as React from 'react';
import { ChevronDownIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { EntitlementView } from '@/types/billing-ui';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { EntitlementMeter } from '@/components/betterpay/entitlement-meter';

export interface UsageSummaryProps {
  entitlements: EntitlementView[];
  title?: string;
  description?: string;
  /** e.g. "12 days left in cycle" */
  periodLabel?: string;
  /** Warn threshold for meters (0–1). */
  warnAt?: number;
  /** Collapse list when more than this many (default 3). 0 = never collapse. */
  collapseAfter?: number;
  className?: string;
}

/**
 * Multi-entitlement usage panel with optional expand for long lists.
 */
export function UsageSummary({
  entitlements,
  title = 'Usage',
  description,
  periodLabel,
  warnAt,
  collapseAfter = 3,
  className,
}: UsageSummaryProps) {
  const [expanded, setExpanded] = React.useState(false);
  const collapsible = collapseAfter > 0 && entitlements.length > collapseAfter;
  const visible =
    collapsible && !expanded ? entitlements.slice(0, collapseAfter) : entitlements;
  const hiddenCount = entitlements.length - visible.length;

  return (
    <Card data-slot="usage-summary" className={cn(className)}>
      <CardHeader>
        <div className="flex flex-wrap items-start justify-between gap-2">
          <div className="flex flex-col gap-1">
            <CardTitle className="text-sm font-semibold">{title}</CardTitle>
            {description ? <CardDescription>{description}</CardDescription> : null}
          </div>
          {periodLabel ? (
            <span className="text-xs font-medium text-muted-foreground">{periodLabel}</span>
          ) : null}
        </div>
      </CardHeader>
      <CardContent className="flex flex-col gap-3">
        {entitlements.length === 0 ? (
          <p className="text-sm text-muted-foreground">No metered features on this plan.</p>
        ) : (
          <>
            <div className="grid gap-3">
              {visible.map((item) => (
                <EntitlementMeter
                  key={item.featureId}
                  entitlement={item}
                  warnAt={warnAt}
                  className="shadow-none ring-border/80"
                />
              ))}
            </div>
            {collapsible ? (
              <Button
                variant="ghost"
                size="sm"
                className="self-start"
                onClick={() => setExpanded((v) => !v)}
                aria-expanded={expanded}
              >
                {expanded ? 'Show less' : `Show ${hiddenCount} more`}
                <ChevronDownIcon
                  className={cn(
                    'size-4 transition-transform duration-[var(--duration,180ms)]',
                    expanded && 'rotate-180',
                  )}
                />
              </Button>
            ) : null}
          </>
        )}
      </CardContent>
    </Card>
  );
}
